  }
  private schedule(retry = false) {
    if (this.disposed || this.error?.includes('REJECTED:') || this.error?.includes('VERSION_CONFLICT') || this.error?.includes('REQUEST_ID_CONFLICT')) return;
    clearTimeout(this.timer);
