|   |   `-- First activation mounts MappingEditorCanvas(session)
|   |       |-- Previously visited canvases remain mounted but hidden when inactive
|   |       `-- Workspace epoch / reload key can remount editors
|   `-- Commands address workspace.controllers by document ID
|       `-- Editing contexts remain available even without a mounted editor
|-- CanvasWorkspace [canvasWorkspace.ts]: owns the draft registry and session lifetimes
|   |-- drafts[id] = metadata + stable CanvasSession handle
|   |-- setDrafts(seed containing document, canvas, history)
|   |   `-- Create CanvasSession -> register its controller and subscriptions
|   |-- Metadata update with the same session -> retain controller and editing context
|   |   `-- Refresh saved baseline; persist changes to tracked metadata
|   |-- Session removed or replaced
|   |   `-- Unsubscribe -> remove controller entry -> dispose old session
|   `-- Each CanvasSession [canvasSession.ts]
|       |-- Owns MappingDocumentController and cursor-copy state
|       |-- Exposes read/subscribe stores; mutations go through commands
|       |   |-- document     -> document reference changes
|       |   |   `-- Refresh registry entry for document consumers such as search/explorer
|       |   |-- presentation -> display + diagramViews changes
|       |   |-- selection    -> selection changes
|       |   |-- controls     -> controls changes
|       |   |-- geometry     -> endpointBounds, cell, version changes
|       |   `-- status       -> isDirty, sceneDirty, canUndo, canRedo changes
