|       |       `-- sceneDirty feeds the workspace's dirty-scene ID list
|       |-- Controller notifications publish changed stores synchronously
|       |   `-- canvasRevisionId changed? -> onCommit -> workspace.onPersist([id])
|       |-- Mounted editor owns live geometry and undo navigation
|       |   `-- Pointer/camera samples do not publish session application state
|       `-- Save acknowledgement updates the captured baseline
|           `-- Newer edits can remain dirty after that save
|-- WorkspacePersistence [workspacePersistence.ts]: shared live-state-to-record adapter
|   |-- workspace.onPersist(ids) -> sync only those canvas IDs
|   |   |-- Write metadata + saved baseline
|   |   |-- Per-session cursor -> controller.persistenceChanges(cursor)
|   |   |   |-- Emit incremental history records; advance cursor to delta.sequence
|   |   |   `-- First sync / replaced session
|   |   |       |-- Delete obsolete revision/checkpoint keys in the replacement batch
|   |   |       `-- Skip stored immutable revisions and identical checkpoint deltas
|   |   |-- Capture canvas view records and, when needed, viewport
|   |   `-- Removed draft -> delete its document-prefixed records
