43:         this.known.delete(id); continue;
44:       }
45:       const { representationId: savedRepresentationId, name, hidden, repositoryId, type, savedName, savedScene, savedEdges, revisionId } = draft;
46:       changes.push({ key: prefix + 'metadata', value: { representationId: id, savedRepresentationId, repositoryId, type, name, hidden, version: draft.session.controller.getSnapshot().version } },
